"""Printed 173–174 source area rules, Examples 19–21 and Maple palette outputs."""
from math12_reviewed_unit1 import heading,paragraph,page,command
from math12_reviewed_higher_derivatives import eq,note
def graph(n,poly,regions,xrange,yrange,xticks,yticks,equation,points=[]):
 return {'type':'diagram','caption':'Figure 6.'+str(n),'diagram':{'type':'source-integral-polynomial','title':'Figure 6.'+str(n)+' — '+equation+' with the source bounded regions','polynomial':poly,'regions':regions,'xMin':xrange[0],'xMax':xrange[1],'yMin':yrange[0],'yMax':yrange[1],'xTicks':xticks,'yTicks':yticks,'equation':equation,'points':points}}
PAGES=[page('091_page_1.jpg',173,[paragraph('ii. If f(x) is a continuous function over the interval [a,b], then the area between y = f(x) and the x-axis from x = a to x = b can be found using definite integrals as follows:'),paragraph('For f(x) ≥ 0 over [a,b], the area is:'),eq(r'\mathrm{Area}=\int_a^b[+f(x)]\,dx'),paragraph('For f(x) ≤ 0 over [a,b], the area is:'),eq(r'\mathrm{Area}=\int_a^b[-f(x)]\,dx'),paragraph('If f(x) is positive for some values of x and negative for others on an interval (as in Figure 6.6), then, the area between the graph of y = f(x) and the x-axis can be found by (dividing the interval into subintervals over which f(x) is always positive or always negative) taking the sum of the areas of subregions over each subinterval:'),eq(r'\mathrm{Area}=\int_a^bf(x)\,dx=\int_a^c[-f(x)]\,dx+\int_c^b[+f(x)]\,dx=-A+B','ii'),paragraph('In Figure 6.6, A represents the area between y = f(x) and the x-axis from x = a to x = c, and B represents the area between y = f(x) and the x-axis from x = c to x = b. Both A and B are positive quantities. Since f(x) ≥ 0 on the interval [c,b], the area is'),eq(r'\int_c^b[+f(x)]\,dx=B'),paragraph('and f(x) ≤ 0 on the interval [a,c], the area is'),eq(r'\int_a^c[-f(x)]\,dx=-A'),note('The source mixes signed and geometric areas. With A,B both positive, ∫ₐᶜf = −A, ∫ₐᶜ(−f) = A, and ∫ᶜᵇf = B. Thus the signed integral is −A+B, while total area is A+B = ∫ₐᵇ|f(x)|dx. The last displayed source −A for the integral of −f must be +A.'),heading('6.6.5 Application of definite integral as the area under a curve'),heading('Example 19'),paragraph('Find the area between the x-axis and the curve f(x) = x²−4 from x = 0 to x = 4.'),heading('Solution'),paragraph('First find out the x-intercepts of a curve f(x) = x²−4 that can be found by solving the equation of a curve:'),eq(r'x^2-4=0\Rightarrow x=2,-2'),paragraph('The subintervals of the interval [0,4] are therefore [−2,0],[0,2] and [2,4]. The total area of the region in the required interval [0,4] is the sum of the areas of the subregions in the subintervals [0,2] and [2,4]:'),eq(r'\mathrm{Area}=\int_0^2[-f(x)]\,dx+\int_2^4[+f(x)]\,dx,\quad f(x)\le0\mathrm{\ in}\ [0,2],\quad f(x)\ge0\mathrm{\ in}\ [2,4]'),eq(r'=-\int_0^2(x^2-4)\,dx+\int_2^4(x^2-4)\,dx=-\left[\frac{x^3}3-4x\right]_0^2+\left[\frac{x^3}3-4x\right]_2^4'),eq(r'=-[\frac83-8-(0-0)]+[(\frac{64}3-16)-(\frac83-8)]=\frac{16}3+\frac{16}3+\frac{16}3=16\mathrm{\ square\ units}'),paragraph('The sketch of the region is shown in the Figure 6.7.'),graph(7,[-4,0,1],[[0,2],[2,4]],[-2.5,5],[-5,14],[-2,0,2,4],[-4,4,8,12],'f(x) = x² − 4',[[4,12,'(4,12)']]),paragraph('The area over the entire interval [0,4]'),eq(r'A=\int_0^4(x^2-4)\,dx=\left[\frac{x^3}3-4x\right]_0^4=\frac{16}3'),paragraph('is not the correct area. This definite integral does not represent the area over the entire interval [0,4], but is just a real number.'),note('The source lists [−2,0], which is outside the requested [0,4]; only [0,2] and [2,4] belong to this problem. The signed integral 16/3 is the positive area 32/3 minus the negative-region magnitude 16/3, while the total geometric area is 16. It is a meaningful signed result, not an unsigned area.')
]),page('075_page_2.jpg',174,[heading('Example 20'),paragraph('Find the area between the x-axis and the curve f(x) = x²−2x from x = −1 to x = 3.'),heading('Solution'),paragraph('First find out the x-intercepts of a curve f(x) = x²−2x that can be found by solving the equation of a curve:'),eq(r'x^2-2x=0\Rightarrow x=0,2'),paragraph('The subintervals of the interval [−1,3] are therefore [−1,0],[0,2] and [2,3]. The total area of the region in the required interval [−1,3] is the sum of the areas of the subregions in the subintervals [−1,0],[0,2] and [2,3]:'),eq(r'A=\int_{-1}^0[+f(x)]\,dx+\int_0^2[-f(x)]\,dx+\int_2^3[+f(x)]\,dx,\quad f(x)\ge0\mathrm{\ in}\ [-1,0],[2,3]'),eq(r'=\int_{-1}^0(x^2-2x)\,dx-\int_0^2(x^2-2x)\,dx+\int_2^3(x^2-2x)\,dx'),eq(r'=\left[\frac{x^3}3-\frac{2x^2}2\right]_{-1}^0-\left[\frac{x^3}3-\frac{2x^2}2\right]_0^2+\left[\frac{x^3}3-\frac{2x^2}2\right]_2^3'),eq(r'=(0-0)-(-\frac13-1)-[(\frac83-4)-(0-0)]+[(\frac{27}3-9)-(\frac83-4)]=\frac43+\frac43+\frac43=3(\frac43)=4'),paragraph('The sketch of the region is shown in the Figure 6.8.'),graph(8,[0,-2,1],[[-1,0],[0,2],[2,3]],[-1.5,4.5],[-1.5,4],[-1,0,1,2,3,4],[1,3],'f(x) = x² − 2x'),heading('6.6.6 MAPLE command “int” to evaluate definite and indefinite integrals'),paragraph('The use of maple common “int” is illustrated in the following example.'),heading('Example 21'),paragraph('Use MAPLE command ‘int’ to solve. (a). Indefinite integral of a function f(x) = x⁴+x³+x²+x+1 w.r.t variable x. (b). Definite integral of a function f(x) = x² w.r.t variable x. (c). Definite integral of a function f(x) = xeˣ in the interval [0,1].'),heading('Solution'),heading('a. Command:'),command('int(x^4+x^3+x^2+x+1,x);',r'\(\frac15x^5+\frac14x^4+\frac13x^3+\frac12x^2+x\)'),paragraph('Using Palettes: Use cursor button to select integral palette. Click-integral palette, insert the function required, then press “ENTER” key to obtain the integral of a given function;'),eq(r'\int(x^4+x^3+x^2+x+1)\,dx'),eq(r'\frac15x^5+\frac14x^4+\frac13x^3+\frac12x^2+x'),heading('b. Command:'),command('int(x^2,x=0..1);',r'\(\frac13\)'),paragraph('Using Palettes:'),eq(r'\int_0^1x^2\,dx=\frac13'),heading('c. Command:'),command('int(x*exp(x),x=0..1);','1'),paragraph('Using Palettes:'),eq(r'\int_0^1x\exp(x)\,dx=1'),note('These are manually checked expected Maple outputs, not results from an executed Maple session. The indefinite command returns one antiderivative; the full mathematical family adds +C. Part (b) supplies no bounds in its question sentence, but its printed command and palette use [0,1]. The full PDF also repeats this same page at physical 91, right side.')])]
for p in PAGES:
 p['title']='INTEGRATION';p['visualStatus']='Complete native signed/total-area rules, two exact polynomial region graphs, all source area examples and Maple commands/palette equations';p['alternateVerification']={'pdf':'Math Book for 12 class KPTBB.pdf','pdfPage':91 if p['page']==173 else 75,'side':'left' if p['page']==173 else 'right','reason':'All source area signs, split intervals, polynomial graphs, Maple commands and expected outputs visually checked; duplicate 174 additionally checked on physical 91 right.'}
EXAMPLES=[]
def ex(n,q,steps,ans,pg):
 EXAMPLES.append({'id':'we-6-source-'+str(n),'num':str(n),'title':'Example '+str(n),'problem':q,'given':'The source curve/interval or Maple integration request.','method':'Split at sign changes and integrate absolute area, or verify the printed symbolic integration outputs.','steps':steps,'answer':ans,'progressiveSolution':True,'solutionOrigin':'SpaceBook learning enhancement','sourceReferences':[{'page':pg,'verification':'complete source question and working checked'}]})
ex(19,'Find the area between f(x) = x²−4 and the x-axis on [0,4].',['The roots are −2 and 2; only 2 lies within [0,4].','On [0,2], x²−4 ≤ 0; on [2,4], it is nonnegative.','An antiderivative is F(x) = x³/3−4x.','The negative region has geometric area −[F(2)−F(0)] = −(−16/3) = 16/3.','The positive region has area F(4)−F(2) = 16/3−(−16/3) = 32/3.','Add magnitudes: 16/3+32/3 = 16 square units.','The signed whole integral is 32/3−16/3 = 16/3, which differs from total area. The source’s extra interval [−2,0] is outside the question and is not included.'],'16 square units; signed integral 16/3.',173)
ex(20,'Find the area between f(x) = x²−2x and the x-axis on [−1,3].',['Factor f(x) = x(x−2); the sign-change points are 0 and 2.','The function is nonnegative on [−1,0] and [2,3], and nonpositive on [0,2].','Use F(x) = x³/3−x². Its values at −1,0,2,3 are −4/3,0,−4/3,0.','The first region has area F(0)−F(−1) = 4/3.','The middle region has area −[F(2)−F(0)] = 4/3.','The last region has area F(3)−F(2) = 4/3.','Sum the three magnitudes: total area 4. The signed integral is instead 4/3−4/3+4/3 = 4/3.'],'4 square units.',174)
ex(21,'Use Maple int for (a) x⁴+x³+x²+x+1; (b) x²; (c) xeˣ on [0,1].',['(a) Enter int(x^4+x^3+x^2+x+1,x); to integrate with respect to x.','The expected output is x⁵/5+x⁴/4+x³/3+x²/2+x, obtained by integrating each term. Add +C when giving the general indefinite integral.','Differentiate that polynomial to check every original term.','(b) The source solution chooses bounds 0 and 1. Enter int(x^2,x=0..1);.','Its expected value is [x³/3]₀¹ = 1/3. If the bounds were not specified, x² alone would instead define an indefinite request.','(c) Enter int(x*exp(x),x=0..1);. A primitive is eˣ(x−1), giving 0−(−1) = 1.','The same expressions and limits can be entered with the source integral palette. These commands and outputs are manually verified expected results; Maple has not been run.'],'(a) x⁵/5+x⁴/4+x³/3+x²/2+x (+C for the full family); (b) 1/3 using [0,1]; (c) 1.',174)
